#include "model.hpp"
// Дефект: вход может быть несортированным. Исправьте index и проверьте find.
std::vector<Entry> build_index(const std::vector<Entry>& input){return input;}
std::optional<Entry> find(const std::vector<Entry>& index,int query){std::size_t lo=0,hi=index.size();while(lo<hi){auto mid=lo+(hi-lo)/2;if(index[mid].id<query)lo=mid+1;else hi=mid;}if(lo==index.size()||index[lo].id!=query)return std::nullopt;return index[lo];}

